insert into public.courses (id, language, dialect, title, description, cefr_level, goal_tag, position, published, school, prerequisite_ids)
values ('bbbb0002-0000-4000-8000-000000000026', 'en', null, 'Programming Foundations with JavaScript', 'Learn to program by writing real code in your browser: values and expressions, functions, loops, arrays, and strings — every concept practiced against automated tests, not just read about. Structure informed by the open book Eloquent JavaScript by Marijn Haverbeke (CC BY-NC 3.0).', null, 'foundations', 26, true, 'technology', '{}')
