insert into public.lessons (course_id, position, title, kind, body, grammar_notes_md, estimated_minutes)
select 'bbbb0002-0000-4000-8000-000000000026', v.pos, v.title, v.kind, v.body::jsonb, v.notes, v.mins
from (values
  (1, 'Diagnostic: where are you now?', 'quiz', '{"questions":[{"prompt":"In JavaScript, which value means ''a variable has been declared but has no value yet''?","options":["0","null","undefined","\"\""],"answer":2,"explanation":"A binding declared with no assignment holds undefined; null is a value you assign deliberately to mean ''nothing''."},{"prompt":"What does the expression 3 + 4 * 2 evaluate to?","options":["14","11","24","10"],"answer":1,"explanation":"Multiplication binds tighter than addition, so 4*2 = 8 is computed first, then 3 + 8 = 11."},{"prompt":"Which keyword declares a value that will never be reassigned?","options":["let","var","const","def"],"answer":2,"explanation":"const declares a binding you cannot reassign; use it by default and reach for let only when the value must change."},{"prompt":"What does a function do when it reaches a return statement?","options":["Keeps running the next lines","Immediately hands that value back and stops","Prints the value","Loops back to the start"],"answer":1,"explanation":"return ends the function call right away and produces the returned value as the call''s result."},{"prompt":"The array [10, 20, 30] has its value 20 at which index?","options":["0","1","2","20"],"answer":1,"explanation":"Arrays are zero-indexed: index 0 is 10, index 1 is 20, index 2 is 30."},{"prompt":"Which comparison is strictly true: 2 === \"2\"?","options":["true, they look equal","false, different types","it throws an error","undefined"],"answer":1,"explanation":"=== compares value AND type without converting, so a number and a string are never strictly equal."}]}'::jsonb, null, 8),
  (2, 'Values, bindings, and expressions', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Read and predict the result of simple JavaScript expressions, and store results in named bindings. Warm-up: what do you think \"5\" + 1 produces — 6 or \"51\"?"},{"heading":"The idea","text":"A program manipulates values. The basic types you will meet first are numbers (42, 3.14), strings of text (\"hello\"), and booleans (true, false). An expression is any fragment that produces a value: 3 + 4 is an expression that produces 7. A binding — declared with const or let — gives a value a name so you can refer to it later. const x = 10 creates a name x bound to 10; a const can never be reassigned, while a let can. Operators combine values: + adds numbers but joins (concatenates) strings, so \"5\" + 1 is the string \"51\", not 6."},{"heading":"Worked examples","text":"const price = 20; const withTax = price * 1.1; — withTax is 22. The expression 10 % 3 uses the remainder operator and produces 1 (what is left after dividing 10 by 3). Booleans come from comparisons: 5 > 3 is true, 5 === 5 is true, 5 === \"5\" is false because === checks type as well as value. String concatenation builds messages: const name = \"Sam\"; const greeting = \"Hi, \" + name; makes \"Hi, Sam\"."},{"heading":"Your turn","text":"Predict each result, then check in the playground. 1) 7 + 2 * 3. 2) (7 + 2) * 3. 3) \"a\" + \"b\" + \"c\". 4) 9 % 4. 5) 3 === 3. 6) 3 === \"3\". Answers: 1) 13. 2) 27. 3) \"abc\". 4) 1. 5) true. 6) false."},{"heading":"Common mistakes & exit ticket","text":"Mistake: expecting + to add when one side is a string — it concatenates instead. Mistake: using == (loose, converts types) when you almost always want === (strict). Exit: (a) What does \"3\" + 4 produce? (b) Which operator gives the remainder of a division? Answers: the string \"34\"; the % operator."}]}'::jsonb, 'Prefer const by default; switch to let only when you truly need to reassign. This makes reassignment a visible, intentional act.', 12),
  (3, 'Code: your first function', 'code', '{"prompt":"Write a function square(n) that returns n multiplied by itself.","instructions":"A function packages a computation so you can reuse it. Fill in the body so the function returns the right value. Click Run & check — the lesson unlocks when all tests pass.","starter":"function square(n) {\n  // return n times itself\n}\n","tests":[{"label":"square(2) === 4","expr":"square(2) === 4"},{"label":"square(5) === 25","expr":"square(5) === 25"},{"label":"square(0) === 0","expr":"square(0) === 0"},{"label":"square(-3) === 9","expr":"square(-3) === 9"}],"solution":"function square(n) {\n  return n * n;\n}\n"}'::jsonb, null, 12),
  (4, 'Functions, arguments, and return', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Define functions that take arguments and return results, and explain the difference between returning and printing. Warm-up: if a function has no return statement, what value does calling it produce?"},{"heading":"The idea","text":"A function is a reusable piece of a program with a name, a list of parameters, and a body. You call it with arguments, and it hands back a value with return. function add(a, b) { return a + b; } defines add; add(2, 3) calls it and produces 5. Parameters (a, b) are local names for the values passed in. The moment a return runs, the function stops and its value becomes the result of the call. A function that never returns produces undefined."},{"heading":"Worked examples","text":"function greet(name) { return \"Hello, \" + name + \"!\"; } — greet(\"Ada\") produces \"Hello, Ada!\". Functions can make decisions: function sign(n) { if (n > 0) return \"positive\"; if (n < 0) return \"negative\"; return \"zero\"; }. Because return stops the function, sign(5) returns \"positive\" and never checks the other branches. Functions can call other functions: function fourthPower(n) { return square(square(n)); } reuses square from the previous lesson."},{"heading":"Your turn","text":"On paper, decide what each returns. 1) function f(x){ return x + 1; } f(9). 2) function g(){ } g(). 3) function h(a,b){ return a > b; } h(3, 5). 4) function k(n){ if (n % 2 === 0) return \"even\"; return \"odd\"; } k(7). Answers: 1) 10. 2) undefined. 3) false. 4) \"odd\"."},{"heading":"Common mistakes & exit ticket","text":"Mistake: forgetting return, so the function computes a value and then throws it away (returns undefined). Mistake: putting code after a return in the same branch — it never runs. Exit: (a) What does add(4, 4) return for function add(a,b){ return a+b; }? (b) What does a function with no return give back? Answers: 8; undefined."}]}'::jsonb, 'A function without a return statement returns undefined. Returning a value and printing a value are different things — return hands data back to the caller.', 12),
  (5, 'Code: loops and accumulation', 'code', '{"prompt":"Write sumTo(n) that returns 1 + 2 + 3 + ... + n. If n is 0 or less, return 0.","instructions":"Use a loop to add up the numbers from 1 to n, keeping a running total in a variable. Hint: start a total at 0 and add each number to it.","starter":"function sumTo(n) {\n  let total = 0;\n  // loop from 1 to n and add each to total\n  return total;\n}\n","tests":[{"label":"sumTo(5) === 15","expr":"sumTo(5) === 15"},{"label":"sumTo(1) === 1","expr":"sumTo(1) === 1"},{"label":"sumTo(0) === 0","expr":"sumTo(0) === 0"},{"label":"sumTo(-4) === 0","expr":"sumTo(-4) === 0"},{"label":"sumTo(100) === 5050","expr":"sumTo(100) === 5050"}],"solution":"function sumTo(n) {\n  let total = 0;\n  for (let i = 1; i <= n; i++) {\n    total += i;\n  }\n  return total;\n}\n"}'::jsonb, null, 14),
  (6, 'Arrays and iteration', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Store lists of values in arrays, read and change elements by index, and walk through an array with a loop. Warm-up: for the array [7, 8, 9], what is the index of 9?"},{"heading":"The idea","text":"An array is an ordered list of values written in square brackets: const xs = [7, 8, 9]. Each element has an index starting at 0, so xs[0] is 7 and xs[2] is 9. The number of elements is xs.length. You can loop over an array with a for loop from 0 up to length, or with a for...of loop that hands you each element directly. Arrays have helpful methods: xs.push(10) adds to the end, and xs.includes(8) asks whether a value is present."},{"heading":"Worked examples","text":"Summing an array: function total(xs){ let s = 0; for (const x of xs) s += x; return s; } — total([1,2,3]) is 6. Finding the largest: function max(xs){ let m = xs[0]; for (const x of xs) if (x > m) m = x; return m; } — max([3, 9, 4]) is 9. Building a new array: function doubled(xs){ const out = []; for (const x of xs) out.push(x * 2); return out; } — doubled([1,2,3]) is [2,4,6]. Reading xs[xs.length] (one past the end) gives undefined."},{"heading":"Your turn","text":"Given xs = [4, 8, 15, 16]: 1) What is xs.length? 2) What is xs[0] + xs[3]? 3) What does xs[4] give? 4) After xs.push(23), what is xs.length? 5) Is xs.includes(15) true or false? Answers: 1) 4. 2) 20. 3) undefined. 4) 5. 5) true."},{"heading":"Common mistakes & exit ticket","text":"Mistake: looping while i <= xs.length, which runs one step too far and reads undefined; use i < xs.length. Mistake: assuming the last index equals length; it is length - 1. Exit: (a) What is the first index of any non-empty array? (b) How do you get the number of elements? Answers: 0; the .length property."}]}'::jsonb, 'Array indexes start at 0, so the last index of an array with length n is n - 1. Reading past the end gives undefined, not an error.', 12),
  (7, 'Code: transform an array', 'code', '{"prompt":"Write evensOnly(xs) that returns a new array containing only the even numbers from xs, in their original order.","instructions":"Build up a new array. For each number, keep it only if it is even (divisible by 2 with no remainder). Do not change the input array.","starter":"function evensOnly(xs) {\n  const out = [];\n  // add each even number of xs to out\n  return out;\n}\n","tests":[{"label":"evensOnly([1,2,3,4]) is [2,4]","expr":"JSON.stringify(evensOnly([1,2,3,4])) === JSON.stringify([2,4])"},{"label":"evensOnly([1,3,5]) is []","expr":"JSON.stringify(evensOnly([1,3,5])) === JSON.stringify([])"},{"label":"evensOnly([]) is []","expr":"JSON.stringify(evensOnly([])) === JSON.stringify([])"},{"label":"evensOnly([2,4,6]) is [2,4,6]","expr":"JSON.stringify(evensOnly([2,4,6])) === JSON.stringify([2,4,6])"},{"label":"input is not mutated","expr":"(function(){ const a=[1,2,3,4]; evensOnly(a); return a.length === 4; })()"}],"solution":"function evensOnly(xs) {\n  const out = [];\n  for (const x of xs) {\n    if (x % 2 === 0) out.push(x);\n  }\n  return out;\n}\n"}'::jsonb, null, 14),
  (8, 'Checkpoint 1', 'quiz', '{"questions":[{"prompt":"What does the expression 10 % 3 evaluate to?","options":["3","1","0","3.33"],"answer":1,"explanation":"% is the remainder operator: 10 divided by 3 leaves 1."},{"prompt":"For xs = [5, 6, 7], what is xs[xs.length - 1]?","options":["5","6","7","undefined"],"answer":2,"explanation":"length is 3, so the last index is 3 - 1 = 2, holding 7."},{"prompt":"A for loop written as for (let i = 0; i < xs.length; i++) visits which indexes?","options":["1 through length","0 through length","0 through length - 1","only 0"],"answer":2,"explanation":"It starts at 0 and stops before length, covering every valid index 0..length-1."},{"prompt":"What does function f(n){ if (n > 0) return \"+\"; return \"-\"; } f(0) return?","options":["\"+\"","\"-\"","0","undefined"],"answer":1,"explanation":"0 is not greater than 0, so the first return is skipped and the function returns \"-\"."},{"prompt":"Which builds a new array without changing the original?","options":["Pushing into a fresh out array","Reassigning elements of the input","Calling xs.length","Using ==="],"answer":0,"explanation":"Creating a separate out array and pushing into it leaves the input untouched."},{"prompt":"What is the value of \"code\".length?","options":["3","4","5","undefined"],"answer":1,"explanation":"Strings have a length too: \"code\" has 4 characters."}]}'::jsonb, null, 8),
  (9, 'Code: working with strings', 'code', '{"prompt":"Write countVowels(s) that returns how many vowels (a, e, i, o, u) are in the string s. Treat uppercase and lowercase as the same.","instructions":"Lowercase the string first, then check each character against the vowels. Hint: \"aeiou\".includes(ch) tells you whether ch is a vowel.","starter":"function countVowels(s) {\n  let count = 0;\n  // examine each character of s\n  return count;\n}\n","tests":[{"label":"countVowels(\"hello\") === 2","expr":"countVowels(\"hello\") === 2"},{"label":"countVowels(\"XYZ\") === 0","expr":"countVowels(\"XYZ\") === 0"},{"label":"countVowels(\"\") === 0","expr":"countVowels(\"\") === 0"},{"label":"countVowels(\"Education\") === 5","expr":"countVowels(\"Education\") === 5"},{"label":"countVowels(\"AEIOU\") === 5","expr":"countVowels(\"AEIOU\") === 5"}],"solution":"function countVowels(s) {\n  let count = 0;\n  const lower = s.toLowerCase();\n  for (const ch of lower) {\n    if (\"aeiou\".includes(ch)) count++;\n  }\n  return count;\n}\n"}'::jsonb, null, 12),
  (10, 'Capstone: FizzBuzz', 'code', '{"prompt":"Write fizzbuzz(n): return \"Fizz\" if n is divisible by 3, \"Buzz\" if divisible by 5, \"FizzBuzz\" if divisible by both, otherwise the number as a string.","instructions":"This classic exercise ties together conditionals, the remainder operator, and returning strings. Check the both-divisible case first — order matters.","starter":"function fizzbuzz(n) {\n  // your code here\n}\n","tests":[{"label":"fizzbuzz(3) === \"Fizz\"","expr":"fizzbuzz(3) === \"Fizz\""},{"label":"fizzbuzz(5) === \"Buzz\"","expr":"fizzbuzz(5) === \"Buzz\""},{"label":"fizzbuzz(15) === \"FizzBuzz\"","expr":"fizzbuzz(15) === \"FizzBuzz\""},{"label":"fizzbuzz(7) === \"7\"","expr":"fizzbuzz(7) === \"7\""},{"label":"fizzbuzz(30) === \"FizzBuzz\"","expr":"fizzbuzz(30) === \"FizzBuzz\""},{"label":"fizzbuzz(1) === \"1\"","expr":"fizzbuzz(1) === \"1\""}],"solution":"function fizzbuzz(n) {\n  if (n % 15 === 0) return \"FizzBuzz\";\n  if (n % 3 === 0) return \"Fizz\";\n  if (n % 5 === 0) return \"Buzz\";\n  return String(n);\n}\n"}'::jsonb, null, 15)
) as v(pos, title, kind, body, notes, mins)
where not exists (
  select 1 from public.lessons l
  where l.course_id = 'bbbb0002-0000-4000-8000-000000000026' and l.position = v.pos
);
